arguments.command:
cd /tmp/work
cat > resolve.py <<'PYEOF'
import sys,io,zipfile,pickletools
p,member=sys.argv[1],(sys.argv[2] if len(sys.argv)>2 else None)
d=open(p,'rb').read()
if member:
    with zipfile.ZipFile(io.BytesIO(d)) as z: d=z.read(member)
off=0;i=0
STR={"SHORT_BINUNICODE","BINUNICODE","BINUNICODE8","UNICODE","STRING","SHORT_BINSTRING","BINSTRING"}
while off<len(d):
    stack=[]
    try:
        for op,arg,pos in pickletools.genops(d[off:]):
            nm=op.name
            if nm in STR: stack.append(str(arg))
            elif nm=="STACK_GLOBAL":
                a=stack[-2] if len(stack)>=2 else '?'; b=stack[-1] if len(stack)>=1 else '?'
                print(f"  [s{i}@{pos}] STACK_GLOBAL -> {a} {b}")
                stack.append(f"<{a}.{b}>")
            elif nm in("GLOBAL","INST","OBJ"):
                print(f"  [s{i}@{pos}] {nm} -> {arg}")
                stack.append("<g>")
            elif nm=="REDUCE":
                print(f"       REDUCE (callable={stack[-2] if len(stack)>=2 else '?'})")
            elif nm=="STOP": break
            else:
                if nm not in STR: 
                    if nm in("MEMOIZE","BINPUT","PUT","LONG_BINPUT","EMPTY_TUPLE","TUPLE1","TUPLE2","TUPLE3","MARK","FRAME","PROTO"): pass
                    else: stack.append(None)
    except Exception as e:
        print("  err",e);break
    off+=pos+1;i+=1
    if i>8:break
PYEOF
for a in "sample_02.bin" "sample_04.joblib" "sample_05.bin" "sample_07.joblib"; do echo "== $a"; python3 -I resolve.py /app/samples/$a; done

